 /* ASK 371 (W1 7788; rev 4 7799; rev 5 7805): a ROW carry must reach the answer. One content word of the CARRIED BY words, matched by inflection, must also stand in the line's own quoted answer words (its ANSWER and FAILS; on a LINK BROKEN line, the answer quote it gives), must not be a topic word, and must not stand in the line's MEANS words. A carry that shares only topic words is refused. A line that quotes no answer words keeps the earlier test. Normalizer: the ASK 366 FOLD. */
 const CW_F=x=>String(x==null?'':x).replace(/[‘’ʼ´`]/g,"'").replace(/\[[^\]\n]*:[^\]\n]*\]/g,' ').replace(/[\[\]]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
 const CW_IRR={took:'take',taken:'take',taking:'take',takes:'take',found:'find',finding:'find',knew:'know',known:'know',knowing:'know',knoweth:'know',came:'come',coming:'come',cometh:'come',begat:'beget',begotten:'beget',begetteth:'beget',bare:'bear',born:'bear',borne:'bear',beareth:'bear',gave:'give',given:'give',giveth:'give',giving:'give',spake:'speak',spoken:'speak',speaketh:'speak',made:'make',making:'make',maketh:'make',saw:'see',seen:'see',seeth:'see',went:'go',gone:'go',goeth:'go',said:'say',saith:'say',saying:'say'};
 const CW_STOP=new Set('a an and the of to in into on unto upon out up at by for from with without after before till until not no nor or but if that this these those which who whom whose what when where while as so then than there here also all any every each such own same is are was were be been being am art shall will would should may might must can could do did does doth hath have has had his her hers him he she it its they them their thee thou thy thine ye you your my me mine i we us our s'.split(' '));
 const cwStem=w=>{if(CW_IRR[w])return CW_IRR[w];for(const sf of ['eth','est','ing','ed','es','en','s']){if(w.length>sf.length+2&&w.endsWith(sf))return w.slice(0,-sf.length).replace(/(.)\1$/,'$1').replace(/e$/,'');}return w.replace(/e$/,'');};
 const CW_TOP=new Set(['god','son','christ','lord','jesus','holy','ghost'].map(cwStem));
 const cwSet=t=>{const m=new Map();for(const w of CW_F(t).split(' ')){if(!w||CW_STOP.has(w)||/^\d+$/.test(w))continue;const s=cwStem(w);if(!m.has(s))m.set(s,w);}return m;};
 const CW_Q=s=>String(s||'').trim().replace(/^["“]+|["”.]+$/g,'').trim();
 function cwFields(line){const L=String(line||'').replace(/\\+"/g,'"');const re=/(?:^|\s)--\s*(MEANS|ANSWER|FAILS|CARRIED BY|GROUND)\b(?:\s*\[[^\]]*\])?\s*:/gi;const at=[];let m;while((m=re.exec(L)))at.push({k:m[1].toUpperCase(),s:m.index,e:m.index+m[0].length});
  const f={};at.forEach((a,i)=>{const t=L.slice(a.e,i+1<at.length?at[i+1].s:L.length);if(!(a.k in f))f[a.k]=CW_Q(t);});
  if(!f.ANSWER&&!f.FAILS){const q=L.match(/\banswer(?:'s)?(?:\s+words\s+that\s+fail)?,?\s*(?:\[[CD]R[1-4]\],?\s*)?["“]([^"”]{3,})["”]/i);if(q)f.QUOTE=q[1];}return f;}
 function cwCheck(line,words){const f=cwFields(line);const ans=[f.ANSWER,f.FAILS,f.QUOTE].filter(Boolean).join(' | ');if(!ans)return null;
  const C=cwSet(words),A=cwSet(ans),M=cwSet(f.MEANS||'');const sh=[...C.keys()].filter(s=>A.has(s)&&!M.has(s));const real=sh.filter(s=>!CW_TOP.has(s));const tw=sh.filter(s=>CW_TOP.has(s)).map(s=>C.get(s));
  if(real.length)return {pass:true,note:'carry word check (ASK 371): shares '+real.map(s=>C.get(s)+(A.get(s)!==C.get(s)?'/'+A.get(s):'')).join(', ')+' with the answer'+(tw.length?'; topic words also seen: '+tw.join(', '):'')};
  return {pass:false,why:'its CARRIED BY words share '+(tw.length?'only topic words ('+tw.join(', ')+')':'no content word')+' with the answer\'s own quoted words outside the pressed MEANS, so the row does not reach the answer it is said to carry (ASK 371)'};}
